SELECT e.*
FROM arte_ai_tool_execution_event e
         INNER JOIN arte_ai_tool_call c ON c.call_id = e.call_id
WHERE e.trace_id = #{traceId}
  AND c.owner_id = #{ownerId}
ORDER BY e.occurred_at, e.id

